body.tpl-classic_formal { font-family: 'Times New Roman', Georgia, serif; font-size: 11px; color: #111827; margin: 0; padding: 20px; background-color: #ffffff; }
.tpl-classic_formal .header-table { width: 100%; border-bottom: 3px double #111827; padding-bottom: 10px; margin-bottom: 15px; }
.tpl-classic_formal .company-name { font-size: 18px; font-weight: bold; color: {{ $accentColor ?: '#111827' }}; text-transform: uppercase; letter-spacing: 1px; }
.tpl-classic_formal .company-address { font-size: 9.5px; color: #374151; }
.tpl-classic_formal .payslip-title { font-size: 18px; font-weight: bold; color: {{ $accentColor ?: '#111827' }}; text-align: right; text-transform: uppercase; letter-spacing: 1px; }
.tpl-classic_formal .employee-info-table { width: 100%; border: 1px solid #374151; border-collapse: collapse; margin-bottom: 15px; }
.tpl-classic_formal .employee-info-table td { border: 1px solid #6b7280; padding: 6px 10px; font-size: 10px; }
.tpl-classic_formal .meta-label { color: #111827; font-weight: bold; }
.tpl-classic_formal .meta-val { font-weight: normal; color: #111827; }
.tpl-classic_formal .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-classic_formal .components-table th { border: 1px solid #111827; background-color: #f3f4f6; color: #111827; padding: 7px; font-size: 10px; text-transform: uppercase; font-weight: bold; }
.tpl-classic_formal .components-table td { border: 1px solid #4b5563; padding: 6px 8px; font-size: 10px; }
.tpl-classic_formal .net-pay-box { border: 2px solid #111827; background-color: #f9fafb; color: #111827; padding: 10px 14px; margin-bottom: 15px; }
.tpl-classic_formal .net-amount { font-size: 15px; font-weight: bold; color: {{ $accentColor ?: '#111827' }}; }
.tpl-classic_formal .net-words { font-size: 9.5px; font-style: italic; text-align: right; color: #374151; }
.tpl-classic_formal .footer-note { text-align: center; font-size: 8.5px; color: #4b5563; margin-top: 20px; border-top: 3px double #111827; padding-top: 6px; }
